<style>
.av-shell{max-width:1200px;margin:auto;padding:32px}.av-hero{background:linear-gradient(115deg,#eef5ff,#d7e7ff);border:1px solid #b9d0ff;border-radius:18px;padding:25px;display:flex;align-items:center;justify-content:space-between;gap:20px}.av-hero h1{font-size:27px;margin:5px 0}.av-hero p{color:#526b91;margin:8px 0}.av-board{margin-top:20px;border:1px solid #d1def3;border-radius:16px;background:white;overflow:hidden}.av-toolbar{padding:18px;background:#f5f8ff;display:flex;gap:12px;align-items:center;flex-wrap:wrap}.av-toolbar input{flex:1;min-width:180px}.av-table{width:100%;border-collapse:collapse}.av-table th{background:#e2edff;color:#244474;text-align:left;font-size:12px;padding:14px}.av-table td{padding:16px 14px;border-bottom:1px solid #e7edf7;font-size:13px}.av-table small{display:block;color:#637998;margin-top:4px}.av-status{display:inline-block;border-radius:7px;padding:6px 9px;font-weight:700;background:#edf2fa;color:#52647f}.av-status.reviewed{background:#dcfce7;color:#166534}.av-status.needs_correction{background:#ffedd5;color:#9a3412}.av-status.incomplete{background:#fee2e2;color:#991b1b}.av-dialog{width:min(580px,calc(100vw - 32px));border:1px solid #c7d8f4;border-radius:18px;padding:24px;color:#17335d}.av-dialog::backdrop{background:#10234488;backdrop-filter:blur(4px)}.av-dialog h2{font-size:20px;margin-top:0}.av-dialog label{display:block;font-weight:600;margin:18px 0 7px}.av-dialog textarea{min-height:95px;resize:vertical}.av-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}@media(max-width:650px){.av-shell{padding:16px}.av-hero{align-items:flex-start;flex-direction:column}}
</style>
<main class="dashboard-main"><div class="av-shell">
<header class="av-hero"><div><small>REGISTRAR / ACADEMIC RECORDS</small><h1>Academic Validation</h1><p>Review completeness, record corrections, and preserve the source grades.</p></div><a class="btn btn-light" href="academic-history.php">Academic history</a></header>
<section class="av-board"><div class="av-toolbar"><label for="avSearch">Find a record</label><input id="avSearch" class="form-control" placeholder="Student, program, or school year"><label for="avFilter">Review status</label><select id="avFilter" class="form-control"><option value="">All records</option><option value="pending">Pending review</option><option value="needs_correction">Needs correction</option><option value="incomplete">Incomplete</option><option value="reviewed">Reviewed</option></select><span id="avCount" role="status"></span></div><div class="table-responsive"><table class="av-table"><thead><tr><th>Student / program</th><th>Academic period</th><th>Validation</th><th>Latest review</th><th>Action</th></tr></thead><tbody id="avRows"><tr><td colspan="5">Loading records…</td></tr></tbody></table></div></section>
<p style="color:#607696;font-size:13px">Correction remarks are recorded locally. Forwarding to Curriculum will be available when its integration is connected.</p>
</div></main>
<dialog id="avDialog" class="av-dialog" aria-label="Review academic record"><form id="avForm"><h2>Review academic record</h2><p id="avIdentity"></p><label for="avStatus">Review result</label><select id="avStatus" class="form-control"><option value="reviewed">Reviewed</option><option value="needs_correction">Needs correction</option><option value="incomplete">Incomplete</option></select><label for="avRemarks">Review remarks</label><textarea id="avRemarks" class="form-control" maxlength="4000" placeholder="Identify missing records or the correction needed."></textarea><div id="avDiagnostics" role="status"></div><details><summary>Review history</summary><div id="avHistory"></div></details><p id="avMessage" role="status"></p><div class="av-actions"><button type="button" class="btn btn-light" id="avCancel">Cancel</button><button class="btn btn-primary" type="submit" id="avSave">Save validation</button></div></form></dialog>
<script>
(()=>{const readOnly=<?= getCurrentUserRole()==='department_head'?'true':'false' ?>,labels={reviewed:'Reviewed',needs_correction:'Needs correction',incomplete:'Incomplete'},rows=document.getElementById('avRows'),dialog=document.getElementById('avDialog');let records=[],selected=null,returnFocus;
const cell=(tr,text,small)=>{const td=document.createElement('td');td.textContent=text;if(small){const el=document.createElement('small');el.textContent=small;td.append(el);}tr.append(td);return td;};
function render(){rows.replaceChildren();const q=document.getElementById('avSearch').value.toLowerCase();const status=document.getElementById('avFilter').value;const visible=records.filter(r=>(!status||(r.review_status||'pending')===status)&&[r.first_name,r.last_name,r.student_number,r.course,r.school_year].join(' ').toLowerCase().includes(q));document.getElementById('avCount').textContent=visible.length+' records';for(const r of visible){const tr=document.createElement('tr');cell(tr,r.first_name+' '+r.last_name,r.student_number+' · '+r.course);cell(tr,r.school_year||'Not provided',r.semester||'No semester');const badge=document.createElement('span');badge.className='av-status '+(r.review_status||'');badge.textContent=labels[r.review_status]||'Pending review';cell(tr,'').append(badge);cell(tr,r.reviewer||'Not reviewed',r.remarks||'');const td=cell(tr,'');if(!readOnly){const btn=document.createElement('button');btn.className='btn btn-light';btn.textContent='Review record';btn.onclick=()=>{selected=r;returnFocus=btn;document.getElementById('avIdentity').textContent=r.first_name+' '+r.last_name+' · '+r.school_year+' · '+(r.semester||'');document.getElementById('avStatus').value=r.review_status||'reviewed';document.getElementById('avRemarks').value=r.remarks||'';document.getElementById('avMessage').textContent='';document.getElementById('avDiagnostics').textContent='Checking received records…';document.getElementById('avHistory').textContent='Loading review history…';dialog.showModal();fetch('../api/academic-validations.php?record_id='+r.id).then(x=>x.json()).then(d=>{const history=document.getElementById('avHistory');history.replaceChildren();if(!d.success)throw Error(d.message);const diagnostics=document.getElementById('avDiagnostics');diagnostics.replaceChildren();if(d.diagnostics){for(const issue of d.diagnostics.issues){const p=document.createElement('p');p.textContent=issue;diagnostics.append(p);}const source=document.createElement('p');source.textContent='Sources: '+d.diagnostics.sources.join(', ')+' · Last received: '+(d.diagnostics.last_received_at||'Not recorded')+' · '+d.diagnostics.grading_scale+'. '+d.diagnostics.limitation;diagnostics.append(source);const receipts=document.createElement('details'),heading=document.createElement('summary');heading.textContent='Received source rows';receipts.append(heading);for(const receipt of d.diagnostics.source_receipts||[]){const line=document.createElement('p');line.textContent=[receipt.subject,receipt.source||'Unspecified source',receipt.source_reference||'No source reference',receipt.received_at||'Receipt time not recorded'].join(' · ');receipts.append(line);}diagnostics.append(receipts);}for(const h of d.history){const p=document.createElement('p');p.textContent=(labels[h.review_status]||h.review_status)+' · '+h.created_at+' · '+(h.reviewer||'Staff')+(h.remarks?' — '+h.remarks:'');history.append(p);}if(!d.history.length)history.textContent='No validations recorded yet.';}).catch(e=>document.getElementById('avHistory').textContent=e.message);};td.append(btn);}else td.textContent='Read-only';rows.append(tr);}if(!visible.length){const tr=document.createElement('tr'),td=cell(tr,'No academic records in your assigned programs match this search.');td.colSpan=5;rows.append(tr);}}
async function load(){const r=await fetch('../api/academic-validations.php'),data=await r.json();if(!data.success)throw Error(data.message||'Could not load records');records=data.records;render();}
document.getElementById('avSearch').oninput=render;document.getElementById('avFilter').onchange=render;document.getElementById('avCancel').onclick=()=>dialog.close();dialog.addEventListener('close',()=>returnFocus?.focus());document.getElementById('avForm').onsubmit=async e=>{e.preventDefault();const save=document.getElementById('avSave');save.disabled=true;try{const r=await fetch('../api/academic-validations.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({record_id:selected.id,status:document.getElementById('avStatus').value,remarks:document.getElementById('avRemarks').value})}),d=await r.json();if(!d.success)throw Error(d.message);await load();dialog.close();}catch(err){document.getElementById('avMessage').textContent=err.message;}finally{save.disabled=false;}};load().catch(e=>{rows.replaceChildren();const tr=document.createElement('tr'),td=cell(tr,e.message);td.colSpan=5;rows.append(tr);});})();
</script>
